import {editionFor} from './resource-editions.js';
import {assetHref} from "./data-loader.js";
import {courses} from "./catalogue-data.js";
import { sequenceModel, goalFields } from './sequence-model.js';
import { mount } from '../slides/widgets.js';
import { mountExperiment } from './lab/mount.js';
import { resolveRef } from './lab/registry.js';
import { labs } from './content.js';
const P=(fr,en)=>[fr,en], E=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
// Four destinations, none compulsory. The six stage names of the first design stay valid as aliases (old links, tests).
const tabs=[['cours',P('Cours','Lesson')],['manipuler',P('Manipuler','Explore')],['exercices',P('Exercices','Exercises')],['documents',P('Documents','Documents')]];
const aliases={prepare:'cours',understand:'cours',experiment:'manipuler',practice:'exercices',review:'exercices'};
export const chapterTab=k=>tabs.some(([id])=>id===k)?k:(aliases[k]||'cours');
const kinds={chapter:P('Livret élève','Student booklet'),teacher:P('Corrigés et guide professeur','Solutions and teacher guide'),fluency:P('Automatismes','Fluency'),'fluency-solutions':P('Corrigés des automatismes','Fluency solutions')};
const courseNames={seconde:'Seconde',premiere:'Première spécialité',terminale:'Terminale spécialité',expertes:'Mathématiques expertes',stmg:'Terminale STMG'};
export function chapterSequencePage(c,tab,t,chapters){
 tab=chapterTab(tab);
 const prev=chapters.find(x=>x.course===c.course&&x.number===c.number-1),next=chapters.find(x=>x.course===c.course&&x.number===c.number+1);
 return `<main id="main" tabindex="-1" class="page chapter-page sequence-page"><nav class="breadcrumb" aria-label="${t(P('Fil d’Ariane','Breadcrumb'))}"><a class="back-library" href="#resources">${t(P('Tous les chapitres','All chapters'))}</a></nav><div class="chapter-heading"><p class="muted">${E(t(courses.find(x=>x.id===c.course)?.title||[c.course,c.course]))} · ${t(P('Chapitre','Chapter'))} ${c.number}</p><h1>${E(t(c.title))}</h1></div><nav class="chapter-tabs" aria-label="${t(P('Sections du chapitre','Chapter sections'))}"><ul>${tabs.map(([k,label])=>`<li><a href="#chapter/${c.id}/${k}" ${k===tab?'aria-current="page"':''}>${E(t(label))}</a></li>`).join('')}</ul><a class="chapter-slides" href="${E(assetHref("./slides/player.html"))}&amp;deck=${c.id}">${t(P('Présenter et manipuler','Present and explore'))} ↗</a></nav><section class="sequence-content" id="chapter-sequence" data-step="${tab}" aria-busy="true">${tab==='documents'?chapterDocuments(c,t(P('fr','en'))==='en'?1:0):`<p role="status">${t(P('Chargement du chapitre…','Loading chapter…'))}</p>`}</section><nav class="chapter-next" aria-label="${t(P('Ordre des chapitres','Chapter order'))}">${prev?`<a href="#chapter/${prev.id}">← ${E(t(prev.title))}</a>`:'<span></span>'}${next?`<a href="#chapter/${next.id}">${E(t(next.title))} →</a>`:''}</nav></main>`;
}
let mathPromise;
async function math(root){
 if(!mathPromise){mathPromise=(async()=>{
  if(!window.MathJax?.startup?.promise){
   window.MathJax={startup:{typeset:false},svg:{fontCache:'none'},options:{enableAssistiveMml:true},tex:{inlineMath:[['\\(','\\)']],displayMath:[['\\[','\\]']],macros:{pgcd:'\\operatorname{PGCD}',ppcm:'\\operatorname{PPCM}',/*mx-math*/"N":"\\mathbb{N}","Z":"\\mathbb{Z}","D":"\\mathbb{D}","Q":"\\mathbb{Q}","R":"\\mathbb{R}","C":"\\mathbb{C}","vect":["\\overrightarrow{#1}",1],"vi":"\\vec{\\imath}","vj":"\\vec{\\jmath}","vk":"\\vec{k}","norm":["\\left\\lVert #1\\right\\rVert",1],"vc":["\\begin{pmatrix}#1\\\\#2\\end{pmatrix}",2],"deter":["\\det\\left(#1,#2\\right)",2],"abs":["\\left\\lvert #1\\right\\rvert",1],"dd":"\\,\\mathrm{d}","e":"\\mathrm{e}","Card":"\\operatorname{Card}","E":"\\operatorname{E}","V":"\\operatorname{V}","degre":"^{\\circ}","un":["\\,\\mathrm{#1}",1],"sci":["#1\\times10^{#2}",2],"llbracket":"\\mathopen{[\\mkern-3mu[}","rrbracket":"\\mathclose{]\\mkern-3mu]}"/*end mx-math*/}}};
   await new Promise((resolve,reject)=>{const s=document.createElement('script');s.src='./vendor/mathjax-tex-svg.js';s.onload=resolve;s.onerror=reject;document.head.append(s);});
  }
  await window.MathJax.startup.promise;
 })();}
 try {await mathPromise;if(root.isConnected){await window.MathJax.typesetPromise([root]);}}catch{mathPromise=null;}
}
function fileLink(f,L,label,page=1){if(!f)return '';const edition=editionFor(f,L?'en':'fr');if(!edition)return `<p class="resource-note">${E(label)} · ${P('Édition française indisponible','English edition unavailable')[L]}</p>`;const {path,bytes,pages}=edition;return `<a class="document-link" href="./${E(assetHref(path.replace(/^\.\//,'')))}#page=${page}" target="_blank" rel="noopener">${E(label)}<span>PDF · ${pages} p.${bytes?' · '+Math.round(bytes/1024)+(L?' KB':' Ko'):''}</span></a>`;}

function slideBody(s,id,L){if(s.k==='code')return `<pre class="sequence-code"><code>${E((s.b[L]||'').replaceAll('&lt;','<').replaceAll('&gt;','>').replaceAll('&amp;','&'))}</code></pre>`;const figs=(s.f||[]).map(p=>`<figure class="sequence-figure"><img loading="lazy" src="./slides/fig/${id}-${p[L]}${L?'-en':''}.svg" alt="${E(s.t[L])}"></figure>`).join('');return `<div class="sequence-maths">${s.b[L]||''}</div>${figs}`;}
function taskHelp(s,L){return (s.hints||[]).map((hint,i)=>`<details><summary>${P('Aide','Hint')[L]} ${i+1}</summary><div class="sequence-maths">${hint[L]}</div></details>`).join('');}
function questionCards(items,c,L){return items.map(s=>`<article class="sequence-card"><h3>${E(s.t[L])}</h3>${slideBody(s,c.id,L)}${taskHelp(s,L)}${s.a?`<details><summary>${P('Correction : après une réponse rédigée','Solution: after writing your answer')[L]}</summary><div class="sequence-maths">${s.a[L]}</div></details>`:''}</article>`).join('');}
function chapterDocuments(c,L){return `<h2>${P('Les supports du chapitre','Chapter resources')[L]}</h2><p>${P('Le cours web, le livret complet et le diaporama ont des usages complémentaires. Choisis le support selon la tâche.','The web lesson, complete booklet and slide deck serve complementary purposes. Choose the resource for your task.')[L]}</p><div class="sequence-documents">${c.files.map(f=>{const label=(kinds[f.kind]||P('Document','Document'))[L]+(f.title?' · '+f.title[L]:'');const link=fileLink(f,L,label);return ['teacher','fluency-solutions'].includes(f.kind)?`<details class="sequence-card"><summary>${E(label)}</summary>${link}</details>`:`<article class="sequence-card">${link}</article>`;}).join('')}<article class="sequence-card"><h3>${P('Présenter et manipuler','Present and explore')[L]}</h3><a href="${E(assetHref("./slides/player.html"))}&amp;deck=${c.id}">${P('Ouvrir le diaporama interactif','Open the interactive slide deck')[L]} ↗</a> <a href="${E(assetHref(`./slides/export/${c.id}.html`))}" download>${P("Télécharger HTML","Download HTML")[L]}</a></article></div>`;}
// The laboratory references of a chapter (manifest `labs`): the first one is mounted inline, lazily; each has its link.
function labBlock(c,L){
 const refs=(c.labs||[]).map(ref=>({ref,r:resolveRef(ref)})).filter(x=>x.r);if(!refs.length)return '';
 const title=({ref,r})=>{const l=labs.find(x=>x.id===r.experiment.id);return (l?.short||r.experiment.short)[L]+(r.explicit?' · '+(r.index+1)+'/'+r.experiment.missions.length:'');};
 return `<section class="chapter-lab" aria-labelledby="chapter-lab-title"><h3 id="chapter-lab-title">${P('Dans le laboratoire','In the laboratory')[L]}</h3><div class="chapter-lab-host lab2-host" data-lab-ref="${E(refs[0].ref)}"></div><ul class="chapter-lab-links">${refs.map(x=>`<li><a class="secondary" href="#lab/${E(x.ref)}">${P('Ouvrir dans le laboratoire','Open in the laboratory')[L]} · ${E(title(x))}</a></li>`).join('')}</ul></section>`;
}
// Mounts the host when it scrolls into view (at once without IntersectionObserver); returns what destroys it.
function lazyLab(host,L){
 let api=null,observer=null,gone=false;
 const start=()=>{if(gone||api)return;api=mountExperiment(host,host.dataset.labRef,{mode:'inline',lang:L?'en':'fr'});};
 if(typeof IntersectionObserver==='function'){observer=new IntersectionObserver(es=>{if(es.some(e=>e.isIntersecting)){observer.disconnect();start();}});observer.observe(host);}else start();
 return{destroy(){gone=true;observer?.disconnect();api?.destroy();api=null;}};
}
export function mountChapterSequence(c,t){
 const root=document.getElementById('chapter-sequence');if(!root)return()=>{};
 const L=t(P('fr','en'))==='en'?1:0;let cancelled=false,live=[];const controller=new AbortController();
 (async()=>{
  try{
   const r=await fetch(assetHref(`./slides/data/${encodeURIComponent(c.id)}.json`),{cache:"no-store",signal:controller.signal});if(!r.ok)throw Error(r.status);const deck=await r.json();if(cancelled)return;
   const model=sequenceModel(deck),step=root.dataset.step,fields=goalFields(model.goals,L),chapter=c.files.find(f=>f.kind==='chapter'),teacher=c.files.find(f=>f.kind==='teacher');
   if(!fields.length && model.tasks.length)fields.push({label:P('Objectifs proposés à partir des tâches du chapitre','Suggested objectives drawn from the chapter tasks')[L],body:'<ol>'+model.tasks.slice(0,4).map(s=>'<li>'+s.b[L]+'</li>').join('')+'</ol>'});
      const hasExplore=(c.labs||[]).length>0||model.activities.length>0;
   const start=`<aside class="chapter-start"><p><strong>${P('Par où commencer ?','Where to start?')[L]}</strong> ${P('Au choix : ','Your choice: ')[L]}${hasExplore?`<a href="#chapter/${c.id}/manipuler">${P('manipuler d’abord','explore first')[L]}</a>, `:''}${P('lire le cours ci-dessous','read the lesson below')[L]}${model.tasks.length?`${hasExplore?',':''} ${P('ou','or')[L]} <a href="#chapter/${c.id}/exercices">${P('aller aux exercices','go to the exercises')[L]}</a>`:''}.</p></aside>`;
   let html='';
   if(step==='cours'){
    const objectives=fields.map(f=>`<section><h3>${E(f.label)}</h3><div class="sequence-maths">${f.body}</div></section>`).join('');
    const fluency=c.files.filter(f=>f.kind==='fluency').map(f=>fileLink(f,L,P('Vérifier les automatismes avant le chapitre','Check fluency before starting')[L])).join('');
    const diagnostic=model.diagnostics.length?`<details class="sequence-card"><summary>${P('Vérifier ses acquis avant de commencer','Check what you know before starting')[L]}</summary>${questionCards(model.diagnostics,c,L)}</details>`:'';
    html=`${start}${objectives?`<h2>${P('Objectifs et prérequis','Objectives and prerequisites')[L]}</h2><div class="sequence-objectives">${objectives}</div><p class="sequence-note">${P('Ces objectifs viennent du chapitre. Ils ne constituent pas une nouvelle prescription de programme.','These objectives come from the chapter; they are not a new curriculum requirement.')[L]}</p>`:''}${fluency}${diagnostic}<h2 id="le-cours">${P('Le cours','The lesson')[L]}</h2><p>${P('Chaque notion est suivie d’un exemple et des points de vigilance qui lui correspondent.','Each idea is followed by a related example and points to watch.')[L]}</p><nav aria-label="${P('Notions','Ideas')[L]}"><ol class="sequence-index">${model.lessons.map((s,i)=>`<li><a href="#chapter/${c.id}/cours/${i}" data-scroll="notion-${i}">${E(s.title[L])}</a></li>`).join('')}</ol></nav>${model.lessons.map((s,i)=>`<article class="sequence-card" id="notion-${i}"><h3><span class="sequence-number">${i+1}</span> ${E(s.title[L])}</h3>${s.statements.map(x=>`<section class="sequence-statement">${x.k==='proof'?`<h4>${P('Justifier et démontrer','Justify and prove')[L]}</h4>`:''}${slideBody(x,c.id,L)}</section>`).join('')}${s.examples.map(x=>`<section class="sequence-example"><h4>${P('Exemple résolu','Worked example')[L]}</h4>${slideBody(x,c.id,L)}${x.a?`<details><summary>${P('Dérouler la résolution','Reveal the worked solution')[L]}</summary><div class="sequence-maths">${x.a[L]}</div></details>`:''}</section>`).join('')}${s.warnings.length?`<aside class="sequence-warning"><h4>${P('Points de vigilance','Points to watch')[L]}</h4>${s.warnings.map(x=>slideBody(x,c.id,L)).join('')}</aside>`:''}${s.tasks.length?`<a class="sequence-task-link" href="#chapter/${c.id}/exercices/${model.tasks.indexOf(s.tasks[0])}">${P('S’entraîner sur cette notion','Practise this idea')[L]} →</a>`:''}</article>`).join('')}`;
   }
   if(step==='manipuler'){
    html=`<h2>${P('Chercher avant de formaliser','Investigate before formalising')[L]}</h2><p>${P('Fais une prévision, teste-la, puis formule une conjecture. Une observation ne remplace pas une démonstration.','Make a prediction, test it, then formulate a conjecture. Observation does not replace proof.')[L]}</p>`;
    html+=labBlock(c,L);
    html+=model.activities.map((s,i)=>s.k==='widget'&&s.w.type==='lab'?((c.labs||[]).some(r=>r.split('/')[0]===s.w.ref.split('/')[0])?'':`<article class="sequence-card"><h3>${E(s.t[L])}</h3><p>${P('Cette activité est une expérience guidée du laboratoire : prévois, manipule, puis lis l’argument.','This activity is a guided experiment of the laboratory: predict, handle, then read the argument.')[L]}</p><a class="secondary" href="#lab/${E(s.w.ref)}">${P('Ouvrir dans le laboratoire','Open in the laboratory')[L]}</a></article>`):s.k==='widget'?`<article class="sequence-card"><h3>${E(s.t[L])}</h3><p>${E(s.b[L])}</p><div class="sequence-experiment" data-widget="${i}"><p class="hint-line"></p><div class="canvas-wrap"></div><div class="wctl"></div><div class="readout"></div></div><details><summary>${P('Mettre en commun','Discuss the findings')[L]}</summary><ul><li>${P('Qu’as-tu modifié ? Qu’est-ce qui reste invariant ?','What did you change? What stayed invariant?')[L]}</li><li>${P('Écris ta conjecture et indique les cas que tu as testés.','Write your conjecture and state the cases you tested.')[L]}</li><li>${P('Cherche un cas qui pourrait la contredire.','Look for a case that could contradict it.')[L]}</li></ul></details></article>`:`<article class="sequence-card"><h3>${E(s.t[L])}</h3>${slideBody(s,c.id,L)}${taskHelp(s,L)}${s.a?`<details><summary>${P('Comparer après la recherche','Compare after investigating')[L]}</summary>${s.a[L]}</details>`:''}</article>`).join('');
    if(!model.activities.length)html+=`<p>${P('Ce chapitre ne contient pas encore d’activité interactive dédiée. Commence par une question du livret, sur papier, avant de consulter le cours.','This chapter does not yet have a dedicated interactive activity. Start with a booklet question on paper before reading the lesson.')[L]}</p>${fileLink(chapter,L,P('Ouvrir le livret élève','Open the student booklet')[L])}`;
   }
   const practiceIntro = model.tasks.length
    ? P('Rédige une réponse justifiée avant d’ouvrir une aide ou une correction. Les questions suivent l’ordre des notions du cours.','Write a justified answer before opening help or solutions. The questions follow the lesson’s order.')[L]
    : P('Ce chapitre ne fournit pas encore de questions web autonomes vérifiées. Travaille les exercices du livret ci-dessous, qui contiennent les données nécessaires.','This chapter does not yet provide verified standalone web questions. Use the booklet exercises below, which include the necessary data.')[L];
   if(step==='exercices')html=`<h2>${P('S’entraîner et réinvestir','Practise and apply')[L]}</h2><p>${practiceIntro}</p>${model.tasks.map((s,i)=>`<article class="sequence-card" id="exo-${i}"><p class="muted">${s.reused?P('Refaire l’exemple sans aide','Redo the example without help')[L]:P('Exercice','Exercise')[L]} ${i+1} · ${E(s.lesson[L])}</p>${slideBody(s,c.id,L)}${taskHelp(s,L)}<p><a href="#chapter/${c.id}/cours/${s.lessonIndex}">${P('Revoir la notion et son exemple : ','Revisit the idea and its example: ')[L]}${E(s.lesson[L])}</a></p>${s.a?`<details><summary>${P('Correction, après avoir cherché','Solution, after trying')[L]}</summary><div class="sequence-maths">${s.a[L]}</div></details>`:''}</article>`).join('')}<section class="sequence-card"><h3>${P('Consolider ou aller plus loin','Consolidate or go further')[L]}</h3>${fileLink(chapter,L,P('Exercices et problèmes du livret','Booklet exercises and problems')[L],chapter?.sections?.practice||1)}<details><summary>${P('Corrigés du livret','Booklet solutions')[L]}</summary>${fileLink(teacher,L,P('Ouvrir la version professeur','Open the teacher edition')[L])}</details></section>`;
   if(step==='exercices')html+=`<h2 id="bilan">${P('Faire le point sans le cours','Take stock without the lesson')[L]}</h2><p>${P('Pour chaque notion, explique la règle avec ses hypothèses, puis refais un exercice sans l’exemple. Une case cochée est un repère personnel, pas une note.','For each idea, explain the rule and its assumptions, then redo an exercise without the example. A checked box is a personal marker, not a grade.')[L]}</p>${questionCards(model.checks,c,L)}<details class="sequence-card"><summary>${P('Ma liste de contrôle personnelle','My personal checklist')[L]}</summary><ul class="sequence-checklist">${model.lessons.map((s,i)=>`<li><label><input type="checkbox"> <span>${E(s.title[L])}</span></label><a href="#chapter/${c.id}/cours/${i}">${P('Revoir','Revisit')[L]}</a></li>`).join('')}</ul></details><section class="sequence-card"><h3>${P('Critères de réussite','Success criteria')[L]}</h3><ul><li>${P('J’énonce les conditions de validité du résultat utilisé.','I state the conditions under which the result applies.')[L]}</li><li>${P('Je choisis une méthode et je justifie chaque étape.','I choose a method and justify each step.')[L]}</li><li>${P('Je vérifie mon résultat par substitution, estimation ou autre contrôle adapté.','I check the result by substitution, estimation or another suitable check.')[L]}</li></ul><p>${P('Si une notion reste fragile, reprends son exemple puis la question correspondante dans S’entraîner.','If an idea is still uncertain, revisit its example, then the matching practice question.')[L]}</p></section>`;
   if(step==='documents')html=chapterDocuments(c,L);
   root.innerHTML=html;root.setAttribute('aria-busy','false');
   const announcement=document.createElement('p');announcement.className='sr-only';announcement.setAttribute('role','status');root.append(announcement);queueMicrotask(()=>{if(!cancelled)announcement.textContent=P('Chapitre chargé','Chapter loaded')[L]+': '+c.title[L];});
   root.querySelectorAll('[data-scroll]').forEach(a=>a.onclick=e=>{e.preventDefault();root.querySelector('#'+a.dataset.scroll)?.scrollIntoView({behavior:'instant',block:'start'});});
   root.querySelectorAll('.chapter-lab-host').forEach(el=>live.push(lazyLab(el,L)));
   root.querySelectorAll('[data-widget]').forEach(el=>{const s=model.activities[+el.dataset.widget];live.push(mount({...s.w,showDelta:false},{host:el.querySelector('.canvas-wrap'),controls:el.querySelector('.wctl'),readout:el.querySelector('.readout'),hint:el.querySelector('.hint-line'),lang:L}));});
   await math(root);
   // #chapter/<id>/cours/<n> opens the lesson at idea n, #chapter/<id>/exercices/<n> at exercise n (old stage names work too).
   const [,,raw,sub]=location.hash.split('/'),target=step==='cours'&&/^\d+$/.test(sub||'')?'notion-'+sub:step==='exercices'&&/^\d+$/.test(sub||'')?'exo-'+sub:step==='exercices'&&raw==='review'?'bilan':'';
   if(!cancelled&&target)root.querySelector('#'+CSS.escape(target))?.scrollIntoView({behavior:'instant',block:'start'});
  }catch(e){if(cancelled)return;root.setAttribute('aria-busy','false');root.innerHTML=`<p>${P('Le contenu du chapitre ne peut pas être chargé. Les livrets restent disponibles.','The chapter content could not be loaded. The booklets remain available.')[L]}</p>${c.files.map(f=>fileLink(f,L,(kinds[f.kind]||P('Document','Document'))[L])).join('')}`;}
 })();
 return()=>{cancelled=true;controller.abort();live.forEach(x=>x.destroy());};
}
